"""Automatic tests for the output generated by rebalance.py.

To run test with records other than the default account ABC,
pipe the program output in, for example
    py rebalance.py 100000 example_book.csv | py test_rebalance.py

With no pipe, the tests run rebalance.py with default example.

Assumptions:
- Share counts are printed with 6 decimal places.
- Buy cash rounds up to the cent. Sell cash rounds down to the cent.
- A piped table can have from 1 to 10 securities.
"""

from __future__ import annotations

import os
import re
import subprocess
import sys
from dataclasses import dataclass
from decimal import Decimal, ROUND_CEILING, ROUND_FLOOR
from pathlib import Path

import pytest

from rebalance import Security, variance

ROOT = Path(__file__).resolve().parent
REBALANCE = ROOT / "rebalance.py"
CENT = Decimal("0.01")
SHARE_STEP = Decimal("0.000001")
SHARE_TEXT = re.compile(r"\d+\.\d{6}")
PIPED_TABLE = "REBALANCE_PIPED_TABLE"


@dataclass(frozen=True)
class ShareRow:
    name: str
    buy_text: str
    sell_text: str
    target_percent: Decimal
    current_percent: Decimal
    price: Decimal

    @property
    def buy(self) -> Decimal:
        return Decimal(self.buy_text)

    @property
    def sell(self) -> Decimal:
        return Decimal(self.sell_text)

    @property
    def security(self) -> Security:
        return Security(self.name, self.target_percent, self.current_percent, self.price)


@dataclass(frozen=True)
class PrintedRun:
    """Execution of rebalance.py."""

    label: str
    account: Decimal
    securities: tuple[Security, ...]
    code: int
    stdout: str
    stderr: str
    header: list[str]
    rows: tuple[ShareRow, ...]
    from_pipe: bool


def run_rebalance(args: list[str]) -> tuple[int, str, str]:
    completed = subprocess.run(
        [sys.executable, str(REBALANCE), *args],
        capture_output=True,
        text=True,
        cwd=ROOT,
    )
    return completed.returncode, completed.stdout, completed.stderr


def parse_table(text: str) -> tuple[Decimal, list[str], tuple[ShareRow, ...]]:
    lines = [line for line in text.splitlines() if line.strip()]
    if len(lines) < 2 or lines[0].split()[0] != "Total":
        pytest.fail("the table has no account total")
    account = Decimal(lines[0].split()[1]).quantize(CENT)
    header = lines[1].split()
    rows = []
    for line in lines[2:]:
        cells = line.split()
        if len(cells) != 6:
            pytest.fail(f"cannot read row: {line}")
        name, buy, sell, target, current, price = cells
        try:
            rows.append(
                ShareRow(name, buy, sell, Decimal(target), Decimal(current), Decimal(price))
            )
        except Exception:
            pytest.fail(f"cannot read shares: {line}")
    return account, header, tuple(rows)


def cash(shares: Decimal, price: Decimal, buy: bool) -> Decimal:
    rounding = ROUND_CEILING if buy else ROUND_FLOOR
    return (shares * price).quantize(CENT, rounding=rounding)


def dollar_gap(security: Security, account: Decimal) -> Decimal:
    """Dollars to buy or sell so the position reaches its target weight."""
    current_value = (security.current_percent / 100 * account).quantize(CENT)
    target_value = (security.target_percent / 100 * account).quantize(CENT)
    return abs(target_value - current_value)


def run_from_output(stdout: str, code: int, stderr: str, from_pipe: bool) -> PrintedRun:
    account, header, rows = parse_table(stdout)
    securities = tuple(row.security for row in rows)
    label = "piped table" if from_pipe else "default account ABC"
    return PrintedRun(label, account, securities, code, stdout, stderr, header, rows, from_pipe)


@pytest.fixture(scope="session")
def printed() -> PrintedRun:
    """The share table from the pipe, or from rebalance.py with no arguments."""
    if PIPED_TABLE in os.environ:
        return run_from_output(os.environ[PIPED_TABLE], 0, "", True)
    code, stdout, stderr = run_rebalance([])
    return run_from_output(stdout, code, stderr, False)


def test_program_exits_cleanly(printed: PrintedRun) -> None:
    if printed.from_pipe:
        assert printed.stdout.strip()
        return
    assert printed.code == 0
    assert printed.stderr == ""


def test_table_lists_every_security_in_order(printed: PrintedRun) -> None:
    assert printed.header == ["Security", "Buy", "Sell", "Target", "Current", "Price"]
    assert [row.name for row in printed.rows] == [security.name for security in printed.securities]


def test_share_counts_have_six_decimal_places(printed: PrintedRun) -> None:
    for row in printed.rows:
        assert SHARE_TEXT.fullmatch(row.buy_text), row.name
        assert SHARE_TEXT.fullmatch(row.sell_text), row.name


def test_a_security_is_never_bought_and_sold(printed: PrintedRun) -> None:
    for row in printed.rows:
        assert row.buy * row.sell == 0, row.name


def test_an_underweight_security_is_bought(printed: PrintedRun) -> None:
    for security, row in zip(printed.securities, printed.rows):
        if security.target_variance >= 0:
            continue
        dollars = dollar_gap(security, printed.account)
        assert row.buy > 0, security.name
        assert row.sell == 0, security.name
        assert cash(row.buy, security.price, buy=True) == dollars, security.name


def test_an_overweight_security_is_sold(printed: PrintedRun) -> None:
    for security, row in zip(printed.securities, printed.rows):
        if security.target_variance <= 0:
            continue
        dollars = dollar_gap(security, printed.account)
        assert row.sell > 0, security.name
        assert row.buy == 0, security.name
        assert cash(row.sell, security.price, buy=False) == dollars, security.name


def test_a_security_already_on_target_is_unchanged(printed: PrintedRun) -> None:
    for security, row in zip(printed.securities, printed.rows):
        if security.target_variance != 0:
            continue
        assert row.buy == 0, security.name
        assert row.sell == 0, security.name


def test_share_cash_rounds_onto_the_gap(printed: PrintedRun) -> None:
    for security, row in zip(printed.securities, printed.rows):
        gap = security.target_variance
        if gap == 0:
            continue
        shares = row.buy if gap < 0 else row.sell
        product = shares * security.price
        dollars = dollar_gap(security, printed.account)
        buy = gap < 0
        rounded = product.quantize(CENT, rounding=ROUND_CEILING if buy else ROUND_FLOOR)
        assert rounded == dollars, security.name
        if product == product.quantize(CENT):
            assert product == dollars, security.name
        elif buy:
            assert product < rounded, security.name
        else:
            assert rounded < product, security.name


def test_share_count_is_the_closest_step_to_the_cash_gap(printed: PrintedRun) -> None:
    for security, row in zip(printed.securities, printed.rows):
        dollars = dollar_gap(security, printed.account)
        if security.target_variance < 0:
            larger = cash(row.buy + SHARE_STEP, security.price, buy=True)
            assert larger > dollars, security.name
        elif security.target_variance > 0:
            smaller = row.sell - SHARE_STEP
            if smaller > 0:
                assert cash(smaller, security.price, buy=False) < dollars, security.name


def test_every_position_lands_on_its_target(printed: PrintedRun) -> None:
    deviations = []
    account = printed.account
    for security, row in zip(printed.securities, printed.rows):
        current_value = (security.current_percent / 100 * account).quantize(CENT)
        target_value = (security.target_percent / 100 * account).quantize(CENT)
        new_value = (
            current_value
            + cash(row.buy, security.price, buy=True)
            - cash(row.sell, security.price, buy=False)
        )
        assert new_value == target_value, security.name
        deviations.append(new_value - target_value)
    assert deviations
    assert variance(deviations) == 0


if __name__ == "__main__":
    os.environ.pop(PIPED_TABLE, None)
    if not sys.stdin.isatty():
        os.environ[PIPED_TABLE] = sys.stdin.read()
    raise SystemExit(pytest.main([__file__, "-v"]))
